#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Node {
    int value;
    struct Node* left;
    struct Node* right;
} Node;

Node* root = NULL;
int used = 0;
int printed = 0;

void preorder(Node* node) {
    if (node == NULL) return;
    printf("%d ", node->value);
    preorder(node->left);
    preorder(node->right);
}

void postorder(Node* node) {
    if (node == NULL) return;
    postorder(node->left);
    postorder(node->right);
    printf("%d ", node->value);
}

void inorder(Node* node) {
    if (node == NULL) return;
    inorder(node->left);
    printf("%d ", node->value);
    inorder(node->right);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <mode> [numbers...]", argv[0]);
        return 1;
    }
    if (strcmp(argv[1], "in") == 0) {
        for (int i = 2; i < argc; i++) {
            int num = strtol(argv[i], NULL, 10);
            Node* new_node = malloc(sizeof(Node));
            new_node->value = num;
            new_node->left = NULL;
            new_node->right = NULL;
            if (root == NULL) {
                root = new_node;
            } else {
                Node* current = root;
                while (1) {
                    if (num < current->value) {
                        if (current->left == NULL) {
                            current->left = new_node;
                            break;
                        }
                        current = current->left;
                    } else {
                        if (current->right == NULL) {
                            current->right = new_node;
                            break;
                        }
                        current = current->right;
                    }
                }
            }
        }
        inorder(root);
    } else if (strcmp(argv[1], "pre") == 0) {
        for (int i = 2; i < argc; i++) {
            int num = strtol(argv[i], NULL, 10);
            Node* new_node = malloc(sizeof(Node));
            new_node->value = num;
            new_node->left = NULL;
            new_node->right = NULL;
            if (root == NULL) {
                root = new_node;
            } else {
                Node* current = root;
                while (1) {
                    if (num < current->value) {
                        if (current->left == NULL) {
                            current->left = new_node;
                            break;
                        }
                        current = current->left;
                    } else {
                        if (current->right == NULL) {
                            current->right = new_node;
                            break;
                        }
                        current = current->right;
                    }
                }
            }
        }
        preorder(root);
    } else if (strcmp(argv[1], "post") == 0) {
        for (int i = 2; i < argc; i++) {
            int num = strtol(argv[i], NULL, 10);
            Node* new_node = malloc(sizeof(Node));
            new_node->value = num;
            new_node->left = NULL;
            new_node->right = NULL;
            if (root == NULL) {
                root = new_node;
            } else {
                Node* current = root;
                while (1) {
                    if (num < current->value) {
                        if (current->left == NULL) {
                            current->left = new_node;
                            break;
                        }
                        current = current->left;
                    } else {
                        if (current->right == NULL) {
                            current->right = new_node;
                            break;
                        }
                        current = current->right;
                    }
                }
            }
        }
        postorder(root);
    } else {
        printf("Invalid mode: %s\n", argv[1]);
        return 1;
    }
    printf("\n");
    return 0;
}
